"""Conservative name-based taxonomy; manual overrides take precedence."""
import re

THEMES = [
    ('Писатели и литература', r'литератур|писател|поэт|булгаков|толсто[йя]|чехов|есенин|паустов|цветаев|маяков|тургенев|достоев|гогол|брюсов|солжениц|лермонтов|грибоедов|белого|дом.*пушкин|квартир.*пушкин|пушкин.*квартир|корне[йя].*чуков|дом.*чуков'),
    ('Искусство и архитектура', r'искусств|художеств|картин|галере|gallery|живопис|скульптур|архитектур|дизайн|икон|тропинин|зверев|глазунов|бурганов|васнецов|шилов|третьяков|теретели|церетели|mmoma|декоративн|гарм|авангард|импрессиони|garage|гараж|бакст|рерих|коненков|андриак'),
    ('Военная история', r'военн|воин|боев|войн|оруж|армии|армей|фронт|побед|обороны|бункер|форт|ветеран|погранич|бронетанк|партизан|разведк|полковод|афган|автомат.*калаш|катастроф.*черноб'),
    ('Наука и техника', r'наук|техник|политех|косм|криптограф|атом|энерги|энергет|эйнштейн|робот|вычисл|компьют|яндекс|ядер|медицин|анатом|патолог|биомед|эксперимент|телефон|истори.*газ|хруничев|прибор|физик|менделеев|курчатов'),
    ('Природа и естествознание', r'природ|дарвин|биолог|зоолог|геолог|минерал|палеонт|ботан|землевед|флор|фауна|животн|эколог|лесн|растен|рыб|гриб|насеком|почв|коневод|охот|лошад|лосин|кошка|собаки'),
    ('Музыка, театр и кино', r'музык|театр|кино|композитор|скрябин|чайков|гнесин|прокофьев|рахманин|шаляпин|балет|танц|мхат|мхт|обухов|плисецк|образцов|высоцк|висоцк|мульт|бахрушин|голованов|мейерхольд|вахтанг'),
    ('Транспорт', r'автомоб|авто.*музе|музе.*авто|транспорт|метро|железнодорож|железн.*дорог|авиаци|авиаком|аэрофлот|велосипед|веломузе|трамва|водного|речного|флот|пароход|мотоцикл|машин|гараж.*особого|ангстрем|warmotors'),
    ('Быт, ремёсла и гастрономия', r'быт|ремес|ремёс|кустар|фарфор|керамик|гончар|шоколад|карамел|пряник|хлеб|кулинар|водк|пив|самовар|ча[йя]|игруш|кукол|куклы|новогод|часов|печат|парфюм|аромат|пахуч|слад|пивовар|марципан|матреш|матрёш|националь.*костюм'),
    ('История и культура', r'истор|краевед|археолог|этнограф|усадьб|кремл|коломенск|царицын|кусков|измайлов|остафьев|москва|москов|город|народ|культур|древн|нумизмат|монет|мемориал|памят|гулаг|репресс|сахаров|ленин|сталин|революц|династи|цар|восток|кочев|росси'),
    ('Религия и духовная культура', r'религи|храм|собор|церков|православ|катол|монастыр|иуда|еврей|будд|ислам|старообряд|старовер|библ|священ|патриарх'),
    ('Спорт', r'спорт|футбол|хоккей|олимпи|динамо|цска|локомотив|спартак'),
    ('Интерактивные и необычные', r'интерактив|иллюзи|магии|магич|фокус|сказ|буратино|пиноккио|советск.*игров|лего|lego|пинбол|pinball|эмоци|тишин|темнот|единорог|необыч|музей.*смех'),
]
OTHER = 'Другие / требуют уточнения'

def classify(name):
    text = name.lower().replace('ё', 'е')
    # The Pushkin Museum of Fine Arts is not a writer's biographical museum.
    art_pushkin = 'пушкин' in text and ('изобразительн' in text or 'гмии' in text)
    matches = [label for label, pattern in THEMES if re.search(pattern, text)]
    if art_pushkin:
        matches = [x for x in matches if x != 'Писатели и литература']
        if 'Искусство и архитектура' not in matches:
            matches.insert(0, 'Искусство и архитектура')
    # A city name alone is not evidence of historical subject matter.
    if 'История и культура' in matches and re.search(r'истор|краевед|археолог|этнограф|усадьб|кремл|коломенск|царицын|кусков|измайлов|остафьев|древн|нумизмат|монет|мемориал|памят|гулаг|репресс|сахаров|ленин|сталин|революц|династи|цар|восток|кочев|народ', text) is None:
        matches.remove('История и культура')
    return matches or [OTHER]
